<script setup>
import {ref,computed,watch,inject,onMounted,shallowRef} from 'vue'
import {useRoute} from 'vue-router'
import JsonDialog from '../components/JsonDialog.vue'
import BindingDialog from '../components/BindingDialog.vue'
const repo=inject('repository'),route=useRoute(),domain=shallowRef(),error=ref(''),loading=ref(true),table=ref('surgeries'),category=ref('all'),search=ref(''),rowSearch=ref(''),view=ref('schema'),page=ref(1),kind=ref('api'),bindings=ref([]),bindingOpen=ref(false),existing=ref(),jsonOpen=ref(false),jsonValue=ref(),jsonTitle=ref('')
const bindingMode=computed(()=>route.path.endsWith('/bindings'))
const catalog=computed(()=>domain.value?.sources.catalog()||[]),categories=computed(()=>[...new Set(catalog.value.map(t=>t.category))])
const tables=computed(()=>catalog.value.filter(t=>(category.value==='all'||t.category===category.value)&&[t.name,t.id].join(' ').toLowerCase().includes(String(search.value||'').trim().toLowerCase())))
const current=computed(()=>catalog.value.find(t=>t.id===table.value)),schema=computed(()=>domain.value?.sources.schema(table.value)||[]),records=computed(()=>domain.value?.sources.rows(table.value)||[])
const fields=computed(()=>schema.value.filter(f=>[f.name,names[f.name]||''].join(' ').toLowerCase().includes(String(rowSearch.value||'').trim().toLowerCase())))
const rows=computed(()=>{const q=String(rowSearch.value||'').trim().toLowerCase();return q?records.value.filter(r=>JSON.stringify(r).toLowerCase().includes(q)):records.value})
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/15)))
const columns=computed(()=>schema.value.slice(0,6)),visibleBindings=computed(()=>bindings.value.filter(b=>b.kind===kind.value))
const names={id:'记录标识',patientId:'患者标识',patientName:'患者姓名',surgeryId:'手术标识',surgeryNo:'手术编号',surgeryName:'手术名称',department:'科室',status:'状态',name:'名称',level:'等级',date:'日期',eventTime:'事件时间',nodeCode:'节点编码',actualTime:'实际时间',plannedTime:'计划时间',surgeonId:'主刀标识',surgeonName:'主刀姓名',operatingRoomId:'手术间标识',operatingRoomNo:'手术间编号'}
const short=v=>{const text=typeof v==='object'?JSON.stringify(v):String(v??'—');return text.length>90?text.slice(0,90)+'…':text}
watch([table,view],()=>{rowSearch.value='';page.value=1});watch(rowSearch,()=>page.value=1);watch(pages,n=>page.value=Math.min(n,page.value))
function json(title,value){jsonTitle.value=title;jsonValue.value=value;jsonOpen.value=true}
function edit(binding){existing.value=binding;bindingOpen.value=true}
function refreshBindings(){try{bindings.value=domain.value.sources.list();error.value=''}catch(e){error.value=e.message}}
async function load(){loading.value=true;try{domain.value=await repo.getDomain();refreshBindings()}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>{{bindingMode?'数据源绑定':'数据管理'}}</h1><p>{{bindingMode?'维护院内外数据源配置与字段映射。':'浏览内部数据集合、字段结构与完整实例。'}}</p></div><VBtn v-if="bindingMode" prepend-icon="tabler-plus" @click="edit()">新建绑定</VBtn></div><VAlert v-if="error" type="error" class="mb-6">{{error}}<VBtn variant="text" @click="load">重试</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate/>
<template v-if="domain"><template v-if="!bindingMode"><VAlert type="info" variant="tonal" class="mb-6">当前为本项目完整演示数据。类型由现有实例推导，覆盖率为字段出现条数 / 实例条数；人工填报空表使用代码字段定义。</VAlert><div class="search-layout"><VCard><VCardText><div class="field"><label>数据分类</label><VSelect v-model="category" :items="[{value:'all',title:'全部分类'},...categories.map(c=>({value:c,title:c}))]"/></div><VTextField v-model="search" placeholder="表名称或英文标识" prepend-inner-icon="tabler-search" clearable aria-label="查找数据表"/></VCardText><VDivider/><VList class="data-catalog"><VListItem v-for="t in tables" :key="t.id" :active="table===t.id" @click="table=t.id" :title="t.name" :subtitle="t.id"><template #append><span class="caption muted">{{t.count}}</span></template></VListItem><VListItem v-if="!tables.length" title="无匹配数据表"/></VList></VCard><VCard style="min-width:0"><div class="section-head"><div><h2>{{current?.name}} <code class="caption muted">{{table}}</code></h2><p>{{records.length.toLocaleString()}} 个实例 · {{schema.length}} 个字段</p></div><VChip variant="tonal" label>模拟数据</VChip></div><VTabs v-model="view" color="primary"><VTab value="schema">表结构</VTab><VTab value="rows">实例浏览</VTab></VTabs><div class="toolbar"><VTextField v-model="rowSearch" :placeholder="view==='schema'?'查找字段名或中文说明':'搜索实例 JSON 全文'" prepend-inner-icon="tabler-search" clearable aria-label="搜索字段或实例"/></div><div class="scroll-table"><VTable v-if="view==='schema'"><thead><tr><th>字段名 / 中文说明</th><th>类型</th><th>覆盖率</th><th>示例</th><th>操作</th></tr></thead><tbody><tr v-for="f in fields" :key="f.name"><td><strong>{{f.name}}</strong><span class="subline">{{names[f.name]||'—'}}</span></td><td><code>{{f.type}}</code><span class="subline">{{f.definition}}</span></td><td class="cell-nowrap">{{f.coverage}}</td><td class="sample-cell">{{short(f.example)}}</td><td class="cell-nowrap"><VBtn v-if="f.example!==undefined" variant="text" size="small" @click="json(f.name+' · 完整示例值',f.example)">查看值</VBtn></td></tr><tr v-if="!fields.length"><td colspan="5" class="text-center muted">没有匹配字段</td></tr></tbody></VTable><VTable v-else><thead><tr><th v-for="f in columns" :key="f.name">{{f.name}}</th><th>操作</th></tr></thead><tbody><tr v-for="(row,i) in rows.slice((page-1)*15,page*15)" :key="i"><td v-for="f in columns" :key="f.name" class="sample-cell">{{short(row[f.name])}}</td><td class="cell-nowrap"><VBtn variant="text" size="small" @click="json(current.name+' · 完整实例',row)">完整实例</VBtn></td></tr><tr v-if="!rows.length"><td :colspan="columns.length+1" class="text-center muted">暂无匹配实例</td></tr></tbody></VTable></div><div v-if="view==='rows'" class="pagination-row"><span>共 {{rows.length.toLocaleString()}} 条 · {{page}} / {{pages}} 页</span><div><VBtn variant="text" size="small" :disabled="page===1" @click="page--">上一页</VBtn><VBtn variant="text" size="small" :disabled="page>=pages" @click="page++">下一页</VBtn></div></div></VCard></div></template>
<template v-else><VAlert type="info" variant="tonal" class="mb-6">配置保存在此浏览器。可校验样例映射；实际接口调用、数据库连接及同步需后端接入。凭据只填写引用标识。</VAlert><VTabs v-model="kind" class="mb-6" color="primary"><VTab value="api">接口类</VTab><VTab value="database">数据库类</VTab></VTabs><div class="catalog-grid"><VCard v-for="b in visibleBindings" :key="b.id"><VCardText><div class="card-kicker"><strong>{{b.scope==='internal'?'院内':'院外'}}系统</strong><VChip :color="b.enabled?'warning':'secondary'" size="small" variant="tonal" label>{{b.enabled?'配置启用 · 未连接':'配置停用'}}</VChip></div><h2 class="subheading">{{b.name}}</h2><p class="definition-desc binding-connection">{{b.kind==='api'?b.connection.method+' '+b.connection.url:b.connection.engine+' · '+b.connection.host+':'+b.connection.port}}</p><p>内部表：{{catalog.find(t=>t.id===b.target)?.name}} <code>{{b.target}}</code></p><p class="caption muted mt-3">{{b.mappings.length}} 条映射 · {{new Date(b.updatedAt).toLocaleString('zh-CN',{hour12:false})}}</p><VBtn variant="tonal" class="mt-5" @click="edit(b)">编辑配置与映射</VBtn></VCardText></VCard></div><VCard v-if="!visibleBindings.length" class="empty"><VIcon icon="tabler-database" size="36" color="secondary"/><h3>暂无{{kind==='api'?'接口':'数据库'}}绑定</h3><p>配置外部来源与内部数据表之间的字段映射。</p><VBtn prepend-icon="tabler-plus" @click="edit()">新建{{kind==='api'?'接口':'数据库'}}绑定</VBtn></VCard></template>
<JsonDialog v-model="jsonOpen" :title="jsonTitle" :value="jsonValue"/><BindingDialog v-model="bindingOpen" :domain="domain" :kind="kind" :existing="existing" @saved="refreshBindings"/></template></template>
<style scoped>.sample-cell{min-width:160px;max-width:260px;white-space:normal;overflow-wrap:anywhere;font-size:12px;line-height:20px}.binding-connection{overflow-wrap:anywhere}</style>
